-- M8 D2: the ledger only grows. Generated by appendOnly() in src/db/helpers/appendOnly.ts —
-- UPDATE and DELETE raise KT001 for everyone, the owner included, and komtru_app holds INSERT and
-- SELECT only; grantRuntimeAccess() finds the trigger on every later migrate run and keeps it that
-- way. Accounts are append-only too: no column on an account is ever meant to change, and an
-- updatable owner_user_id would re-point a balance the journal says belongs somewhere else. A
-- correction is a new reversing journal entry (D2), never an edit.
CREATE TRIGGER komtru_append_only BEFORE UPDATE OR DELETE ON "ledger"."ledger_accounts" FOR EACH ROW EXECUTE FUNCTION platform.reject_mutation();
--> statement-breakpoint
REVOKE ALL ON "ledger"."ledger_accounts" FROM komtru_app;
--> statement-breakpoint
GRANT INSERT, SELECT ON "ledger"."ledger_accounts" TO komtru_app;
--> statement-breakpoint
